={{ (() => {
  const b = $json.body || {};
  const kat = b.kategorie || '';
  const tags = b.tags || [];
  const zutaten = (b.zutaten || []).slice(0, 8).join(', ');
  const schritte = (b.schritte || []).join(' ').replace(/\s+/g, ' ').slice(0, 800);
  const portionen = b.portionen || 1;

  // Diaetvorgabe aus den Tags - ohne sie landet Sauerrahm auf veganen Gerichten
  let diaet = '';
  if (tags.includes('Vegan')) {
    diaet = 'The dish is strictly vegan: no dairy, no cream, no yoghurt, no cheese, no butter, no egg, no honey, no meat, no fish. ';
  } else if (tags.includes('Vegetarisch')) {
    diaet = 'The dish is vegetarian: no meat, no fish, no seafood. ';
  }

  // Szene aus der Rubrik - der alte Prompt kannte nur Abendessen mit Beilage
  let szene;
  if (kat === 'Getr\u00e4nk') {
    szene = 'It is a drink: serve it in a drinking glass, no plate, no cutlery, no side dish. ';
  } else if (kat === 'Snack' || kat === 'Nachtisch') {
    szene = 'It is a ' + (kat === 'Snack' ? 'snack' : 'dessert') + ': serve it on its own as a small portion on a small plate or in a bowl. Do not add rice, potatoes, pasta, bread, salad, dips or any other side dish - only what the ingredient list names appears. ';
  } else if (kat === 'Fruehstueck') {
    szene = 'It is breakfast: a bright scene in soft morning daylight, served on a plate or in a bowl. No dinner plates and no evening side dishes anywhere in the frame. ';
  } else {
    szene = 'It is a main course: serve it on a plain white or light-coloured ceramic plate. Only components named in the ingredient list appear on the plate - do not invent a side dish. ';
  }

  // Die Schritte tragen die Form (Tasse, Glas, Pfanne, Auflaufform). Sie muessen
  // ausdruecklich als Hinweis auf das Ergebnis deklariert werden, sonst rendert
  // das Modell eine Prozessaufnahme mit Haenden und Pfanne.
  const zubereitung = schritte
    ? 'This is how it was prepared - use it only to get the final form, the vessel and the texture right: ' + schritte + ' Show exclusively the finished dish as it is served and eaten. Never show the cooking process, no pans, no pots, no mixing bowls, no raw or half-prepared ingredients, no hands, no steps. '
    : '';

  const menge = portionen > 2
    ? 'The recipe yields ' + portionen + ' portions, but show a single served portion. '
    : '';

  return 'Realistic smartphone snapshot of a home-cooked German dish, beautifully and appetizingly served: "' + (b.name || '') + '". '
    + 'Visible components, and nothing beyond them: ' + zutaten + '. '
    + diaet
    + szene
    + menge
    + zubereitung
    + 'The plate or glass rests on a thin, wide table placemat on a dark, rustic wood dining table with visible wood grain. '
    + 'Setting: cozy home kitchen or dining table, warm ambient light. The table looks like real, everyday life: a glass of water near the main plate, a spice shaker or pepper mill nearby, and slightly out of focus in the background a hint of a second place setting. '
    + 'Never any alcohol, no beer, no wine. '
    + 'The main dish stays the clear focus. The food looks appetizing and nicely plated but not overly perfect - naturally scooped portions rather than smooth symmetrical domes, vibrant colours, a bit of glisten on any sauce, like a home cook proud of their meal, not a staged food-stylist photo. '
    + 'Shot from a relaxed 3/4 angle, like a real person capturing a nice moment of their meal. '
    + 'No text, no watermark, no hands, no logos, no brand labels, no packaging. Photorealistic, 4:5 portrait aspect ratio.';
})() }}

