const res = $input.first().json;
let dataUrl = null;
const msg = res.choices && res.choices[0] && res.choices[0].message;
if (msg && msg.images && msg.images.length) {
  const img = msg.images[0];
  dataUrl = (img.image_url && img.image_url.url) || img.url;
}
if (!dataUrl) {
  const text = JSON.stringify(res);
  const m = text.match(/data:image\/[a-zA-Z]+;base64,[A-Za-z0-9+\/=]+/);
  if (m) dataUrl = m[0];
}
if (!dataUrl) {
  throw new Error('Kein Bild in der Antwort gefunden: ' + JSON.stringify(res).slice(0, 500));
}
const match = dataUrl.match(/^data:(image\/[a-zA-Z]+);base64,(.+)$/);
const mime = match[1];
const base64 = match[2];
const buffer = Buffer.from(base64, 'base64');
const binary = await this.helpers.prepareBinaryData(buffer, 'rezept-bild.png', mime);
return [{ json: { mime }, binary: { data: binary } }];
